import{ar as s,as as a,at as p,au as t}from"./app-5nod3Nrs.js";const e={};function o(c,n){return t(),a("div",null,[...n[0]||(n[0]=[p(`<h1 id="四、前端解析" tabindex="-1"><a class="header-anchor" href="#四、前端解析"><span>四、前端解析</span></a></h1><h2 id="_4-1-cors-中间件" tabindex="-1"><a class="header-anchor" href="#_4-1-cors-中间件"><span>4.1 <code>cors</code> 中间件</span></a></h2><ol><li><p>什么是 CORS？</p><p>当浏览器从 <code>http://localhost:3000</code>（前端）向 <code>http://localhost:5000</code>（后端）发起请求时，由于 <strong>协议、域名或端口不同</strong>，浏览器会阻止响应（同源策略）。<br><strong>CORS（Cross-Origin Resource Sharing）</strong> 是一种机制，允许服务器声明哪些外部源可以访问其资源。</p></li><li><p>安装</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> <span class="token function">install</span> cors</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li><p>基础用法</p><ul><li><p>允许所有来源（开发环境常用）</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> express <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;express&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> cors <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;cors&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> app <span class="token operator">=</span> <span class="token function">express</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 启用 CORS（允许任何 origin）</span></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span><span class="token function">cors</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/api/data&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">req<span class="token punctuation">,</span> res</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">message</span><span class="token operator">:</span> <span class="token string">&#39;Hello from server!&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token number">5000</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><blockquote><p><strong>生产环境不要用 <code>app.use(cors())</code></strong>！应限制可信来源。</p></blockquote></li><li><p>高级配置（生产推荐）</p></li></ol><ul><li><p>仅允许可信域名</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> corsOptions <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">origin</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;http://localhost:3000&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;https://your-frontend.com&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">credentials</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token comment">// 允许携带 Cookie（关键！）</span></span>
<span class="line">  <span class="token literal-property property">optionsSuccessStatus</span><span class="token operator">:</span> <span class="token number">200</span> <span class="token comment">// 旧版浏览器兼容</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span><span class="token function">cors</span><span class="token punctuation">(</span>corsOptions<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>动态判断来源（白名单）</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> whitelist <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&#39;http://localhost:3000&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;https://your-app.com&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> corsOptions <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function-variable function">origin</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">origin<span class="token punctuation">,</span> callback</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 允许无 origin 的请求（如 Postman、curl）</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>origin <span class="token operator">||</span> whitelist<span class="token punctuation">.</span><span class="token function">includes</span><span class="token punctuation">(</span>origin<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token function">callback</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token function">callback</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;Not allowed by CORS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">credentials</span><span class="token operator">:</span> <span class="token boolean">true</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span><span class="token function">cors</span><span class="token punctuation">(</span>corsOptions<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><ol start="5"><li><p>关键选项说明</p><table><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td><code>origin</code></td><td>允许的源（字符串/数组/函数）</td></tr><tr><td><code>credentials: true</code></td><td><strong>必须设置</strong> 才能发送 Cookie（配合前端 <code>withCredentials: true</code>）</td></tr><tr><td><code>methods</code></td><td>允许的 HTTP 方法（默认 <code>&#39;GET,HEAD,PUT,PATCH,POST,DELETE&#39;</code>）</td></tr><tr><td><code>allowedHeaders</code></td><td>允许的请求头（如 <code>&#39;Content-Type&#39;, &#39;Authorization&#39;</code>）</td></tr></tbody></table></li></ol><h2 id="_4-2-cookie-parser-中间件" tabindex="-1"><a class="header-anchor" href="#_4-2-cookie-parser-中间件"><span>4.2 cookie-parser\` 中间件</span></a></h2><ol><li><p>为什么需要它？</p><p>Express 默认不解析 <code>Cookie</code> 请求头。<code>cookie-parser</code> 会：</p><ul><li>自动解析 <code>Cookie</code> 头 → 挂载到 <code>req.cookies</code></li><li>提供签名 Cookie 支持（防篡改）</li></ul></li><li><p>安装</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> <span class="token function">install</span> cookie-parser</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li><p>基础用法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> express <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;express&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> cookieParser <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;cookie-parser&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> app <span class="token operator">=</span> <span class="token function">express</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 解析 Cookie（无签名）</span></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span><span class="token function">cookieParser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/set-cookie&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">req<span class="token punctuation">,</span> res</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 设置 Cookie</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">cookie</span><span class="token punctuation">(</span><span class="token string">&#39;username&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;Alice&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">httpOnly</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string">&#39;Cookie set!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/get-cookie&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">req<span class="token punctuation">,</span> res</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 读取 Cookie</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span>cookies<span class="token punctuation">.</span>username<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;Alice&#39;</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">cookies</span><span class="token operator">:</span> req<span class="token punctuation">.</span>cookies <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>签名 Cookie（防篡改）</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 使用 secret 签名 Cookie</span></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span><span class="token function">cookieParser</span><span class="token punctuation">(</span><span class="token string">&#39;your-secret-key-here&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/set-signed&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">req<span class="token punctuation">,</span> res</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// signed: true 表示签名</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">cookie</span><span class="token punctuation">(</span><span class="token string">&#39;token&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;abc123&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">signed</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string">&#39;Signed cookie set!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/get-signed&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">req<span class="token punctuation">,</span> res</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 读取签名 Cookie（自动验证）</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span>signedCookies<span class="token punctuation">.</span>token<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;abc123&#39;（若被篡改则为 undefined）</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">token</span><span class="token operator">:</span> req<span class="token punctuation">.</span>signedCookies<span class="token punctuation">.</span>token <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>签名原理</strong>：<br> 实际 Cookie 值 = <code>abc123.sig</code>（<code>.sig</code> 是 HMAC 签名），服务端验证签名是否匹配。</p></blockquote></li></ol><h2 id="_4-3-jsonwebtoken" tabindex="-1"><a class="header-anchor" href="#_4-3-jsonwebtoken"><span>4.3 jsonwebtoken</span></a></h2><p><code>jsonwebtoken</code>（简称 <strong>JWT</strong>）是 Node.js 中用于生成和验证 <strong>JSON Web Token</strong> 的标准库。它广泛应用于 <strong>无状态身份认证（Stateless Authentication）</strong> 场景，如 API 登录、单点登录（SSO）等。</p><h3 id="_4-3-1-什么是-jwt" tabindex="-1"><a class="header-anchor" href="#_4-3-1-什么是-jwt"><span>4.3.1 什么是 JWT？</span></a></h3><p>JWT 是一种 <strong>开放标准（RFC 7519）</strong>，用于在网络应用间安全地传递声明（claims）。<br> 一个 JWT 由三部分组成，用 <code>.</code> 分隔：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># 对应表格中的Header.Payload.Signature</span>
<span class="line">xxxxx.yyyyy.zzzzz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>部分</th><th>说明</th></tr></thead><tbody><tr><td><strong>Header</strong></td><td>算法（如 HS256）和类型（JWT）</td></tr><tr><td><strong>Payload</strong></td><td>用户数据（如 <code>{ userId: 1, email: &#39;...&#39; }</code>） + 标准字段（如 <code>exp</code>）</td></tr><tr><td><strong>Signature</strong></td><td>签名（防止篡改）</td></tr></tbody></table><blockquote><p><strong>优点</strong>：</p><ul><li>无状态（服务端无需存储 Session）</li><li>跨域友好（通过 <code>Authorization</code> 头传递）</li><li>自包含（Payload 携带用户信息）</li></ul></blockquote><blockquote><p><strong>缺点</strong>：</p><ul><li>无法主动失效（除非用黑名单或短过期时间）</li><li>Payload 默认不加密（仅 Base64 编码，<strong>不要放敏感信息</strong>）</li></ul></blockquote><h3 id="_4-3-2-安装" tabindex="-1"><a class="header-anchor" href="#_4-3-2-安装"><span>4.3.2 安装</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> <span class="token function">install</span> jsonwebtoken</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>常配合 <code>@types/jsonwebtoken</code>（TypeScript）使用：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> <span class="token function">install</span> --save-dev @types/jsonwebtoken</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></blockquote><h3 id="_4-3-3-核心-api" tabindex="-1"><a class="header-anchor" href="#_4-3-3-核心-api"><span>4.3.3 核心 API</span></a></h3><ol><li><p><code>jwt.sign(payload, secretOrPrivateKey, [options])</code> → 生成 Token</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> jwt <span class="token keyword">from</span> <span class="token string">&#39;jsonwebtoken&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> token <span class="token operator">=</span> jwt<span class="token punctuation">.</span><span class="token function">sign</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">{</span> userId<span class="token operator">:</span> <span class="token number">123</span><span class="token punctuation">,</span> email<span class="token operator">:</span> <span class="token string">&#39;alice@example.com&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token comment">// payload</span></span>
<span class="line">  <span class="token string">&#39;your-secret-key&#39;</span><span class="token punctuation">,</span>                          <span class="token comment">// 密钥（生产环境用强随机字符串）</span></span>
<span class="line">  <span class="token punctuation">{</span> expiresIn<span class="token operator">:</span> <span class="token string">&#39;1h&#39;</span> <span class="token punctuation">}</span>                         <span class="token comment">// 选项：1小时后过期</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>token<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.xxxxx.yyyyy</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常用 <code>options</code>：</p><table><thead><tr><th>选项</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>expiresIn</code></td><td><code>&#39;1h&#39;</code>, <code>&#39;7d&#39;</code>, <code>3600</code></td><td>过期时间（秒或字符串）</td></tr><tr><td><code>issuer</code></td><td><code>&#39;my-app.com&#39;</code></td><td>签发者（<code>iss</code>）</td></tr><tr><td><code>audience</code></td><td><code>&#39;client-app&#39;</code></td><td>接收方（<code>aud</code>）</td></tr><tr><td><code>subject</code></td><td><code>&#39;user-auth&#39;</code></td><td>主题（<code>sub</code>）</td></tr><tr><td><code>algorithm</code></td><td><code>&#39;HS256&#39;</code>（默认）</td><td>签名算法</td></tr></tbody></table><blockquote><p><strong>密钥建议</strong>：</p><ul><li>开发：<code>&#39;secret&#39;</code></li><li>生产：<strong>至少 32 位随机字符串</strong>（用 <code>crypto.randomBytes(32).toString(&#39;hex&#39;)</code> 生成）</li></ul></blockquote></li><li><p><code>jwt.verify(token, secretOrPublicKey, [options])</code> → 验证 Token</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> decoded <span class="token operator">=</span> jwt<span class="token punctuation">.</span><span class="token function">verify</span><span class="token punctuation">(</span>token<span class="token punctuation">,</span> <span class="token string">&#39;your-secret-key&#39;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> jwt<span class="token punctuation">.</span>JwtPayload<span class="token punctuation">;</span></span>
<span class="line">  <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>decoded<span class="token punctuation">.</span>userId<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 123</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>err <span class="token keyword">instanceof</span> <span class="token class-name">jwt</span><span class="token punctuation">.</span>TokenExpiredError<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Token 已过期&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>err <span class="token keyword">instanceof</span> <span class="token class-name">jwt</span><span class="token punctuation">.</span>JsonWebTokenError<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Token 无效&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常见错误类型：</p><table><thead><tr><th>错误</th><th>说明</th></tr></thead><tbody><tr><td><code>TokenExpiredError</code></td><td><code>exp</code> 过期</td></tr><tr><td><code>JsonWebTokenError</code></td><td>签名无效、格式错误等</td></tr><tr><td><code>NotBeforeError</code></td><td><code>nbf</code>（生效时间）未到</td></tr></tbody></table></li><li><p><code>jwt.decode(token, [options])</code> → 仅解码（<strong>不验证签名！</strong>）</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> payload <span class="token operator">=</span> jwt<span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>token<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 返回 null 或 payload 对象</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p><strong>仅用于调试！不要用于认证逻辑</strong>，因为无法保证 Token 未被篡改。</p></blockquote></li></ol><h3 id="_4-3-4-在-express-koa-nestjs-中使用" tabindex="-1"><a class="header-anchor" href="#_4-3-4-在-express-koa-nestjs-中使用"><span>4.3.4 在 Express/Koa/NestJS 中使用</span></a></h3><p><strong>场景：用户登录 → 返回 JWT → 后续请求携带 JWT</strong></p><ul><li><p>步骤 1：用户登录（生成 Token）</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// POST /login</span></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string">&#39;/login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span>req<span class="token punctuation">,</span> res<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">{</span> email<span class="token punctuation">,</span> password <span class="token punctuation">}</span> <span class="token operator">=</span> req<span class="token punctuation">.</span>body<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 1. 验证用户（伪代码）</span></span>
<span class="line">  <span class="token keyword">const</span> user <span class="token operator">=</span> db<span class="token punctuation">.</span><span class="token function">findUserByEmail</span><span class="token punctuation">(</span>email<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>user <span class="token operator">||</span> <span class="token operator">!</span><span class="token function">comparePassword</span><span class="token punctuation">(</span>password<span class="token punctuation">,</span> user<span class="token punctuation">.</span>password<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">status</span><span class="token punctuation">(</span><span class="token number">401</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">{</span> error<span class="token operator">:</span> <span class="token string">&#39;Invalid credentials&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 2. 生成 JWT</span></span>
<span class="line">  <span class="token keyword">const</span> token <span class="token operator">=</span> jwt<span class="token punctuation">.</span><span class="token function">sign</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span> userId<span class="token operator">:</span> user<span class="token punctuation">.</span>id<span class="token punctuation">,</span> email<span class="token operator">:</span> user<span class="token punctuation">.</span>email <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">JWT_SECRET</span><span class="token operator">!</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span> expiresIn<span class="token operator">:</span> <span class="token string">&#39;1d&#39;</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 3. 返回 Token（通常放在 JSON 中，而非 Cookie）</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">{</span> token <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>步骤 2：保护路由（验证 Token）</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 中间件：验证 JWT</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">authenticateToken</span><span class="token punctuation">(</span>req<span class="token punctuation">,</span> res<span class="token punctuation">,</span> next<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> authHeader <span class="token operator">=</span> req<span class="token punctuation">.</span>headers<span class="token punctuation">[</span><span class="token string">&#39;authorization&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> token <span class="token operator">=</span> authHeader <span class="token operator">&amp;&amp;</span> authHeader<span class="token punctuation">.</span><span class="token function">split</span><span class="token punctuation">(</span><span class="token string">&#39; &#39;</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token comment">// Bearer &lt;token&gt;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>token<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">sendStatus</span><span class="token punctuation">(</span><span class="token number">401</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Missing token</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  jwt<span class="token punctuation">.</span><span class="token function">verify</span><span class="token punctuation">(</span>token<span class="token punctuation">,</span> process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">JWT_SECRET</span><span class="token operator">!</span><span class="token punctuation">,</span> <span class="token punctuation">(</span>err<span class="token punctuation">,</span> user<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">sendStatus</span><span class="token punctuation">(</span><span class="token number">403</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Invalid token</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    req<span class="token punctuation">.</span>user <span class="token operator">=</span> user<span class="token punctuation">;</span> <span class="token comment">// 将用户信息挂载到 req</span></span>
<span class="line">    <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 受保护的路由</span></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/profile&#39;</span><span class="token punctuation">,</span> authenticateToken<span class="token punctuation">,</span> <span class="token punctuation">(</span>req<span class="token punctuation">,</span> res<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">{</span> userId<span class="token operator">:</span> req<span class="token punctuation">.</span>user<span class="token punctuation">.</span>userId<span class="token punctuation">,</span> email<span class="token operator">:</span> req<span class="token punctuation">.</span>user<span class="token punctuation">.</span>email <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>步骤 3：前端请求（Axios 示例）</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 登录</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token punctuation">{</span> data <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token keyword">await</span> axios<span class="token punctuation">.</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string">&#39;/login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> email<span class="token punctuation">,</span> password <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">localStorage<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span><span class="token string">&#39;token&#39;</span><span class="token punctuation">,</span> data<span class="token punctuation">.</span>token<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 带 Token 请求</span></span>
<span class="line">axios<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/profile&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">headers</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token string-property property">&#39;Authorization&#39;</span><span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Bearer </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>localStorage<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span><span class="token string">&#39;token&#39;</span><span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><h3 id="_4-3-5-jwt-httponly-cookie-更安全的方案" tabindex="-1"><a class="header-anchor" href="#_4-3-5-jwt-httponly-cookie-更安全的方案"><span>4.3.5 JWT + HttpOnly Cookie（更安全的方案）</span></a></h3><p>为防 XSS，可将 JWT 存入 <strong>HttpOnly Cookie</strong>（前端 JS 无法读取）：</p><ol><li><p>后端设置 Cookie</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 登录成功后</span></span>
<span class="line">res<span class="token punctuation">.</span><span class="token function">cookie</span><span class="token punctuation">(</span><span class="token string">&#39;accessToken&#39;</span><span class="token punctuation">,</span> token<span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  httpOnly<span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">  secure<span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>        <span class="token comment">// 仅 HTTPS</span></span>
<span class="line">  sameSite<span class="token operator">:</span> <span class="token string">&#39;lax&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  maxAge<span class="token operator">:</span> <span class="token number">15</span> <span class="token operator">*</span> <span class="token number">60</span> <span class="token operator">*</span> <span class="token number">1000</span> <span class="token comment">// 15 分钟</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>前端无需处理 Token</p><ul><li>所有请求自动携带 Cookie</li><li>无需手动设置 <code>Authorization</code> 头</li></ul></li><li><p>后端从 Cookie 读取 Token</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 中间件</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">authenticateToken</span><span class="token punctuation">(</span>req<span class="token punctuation">,</span> res<span class="token punctuation">,</span> next<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> token <span class="token operator">=</span> req<span class="token punctuation">.</span>cookies<span class="token punctuation">.</span>accessToken<span class="token punctuation">;</span> <span class="token comment">// 需配合 cookie-parser</span></span>
<span class="line">  <span class="token comment">// ... 验证逻辑同上</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><blockquote><p><strong>优势</strong>：防 XSS<br><strong>劣势</strong>：需处理 CSRF（但 <code>sameSite: &#39;lax&#39;</code> 可缓解）</p></blockquote><h3 id="_4-3-6-refresh-token-机制-解决短过期问题" tabindex="-1"><a class="header-anchor" href="#_4-3-6-refresh-token-机制-解决短过期问题"><span>4.3.6 Refresh Token 机制（解决短过期问题）</span></a></h3><ol><li><strong>Access Token</strong>：短有效期（15 分钟），用于 API 认证</li><li><strong>Refresh Token</strong>：长有效期（7 天），用于获取新 Access Token</li></ol><ul><li>流程：</li></ul><code><pre class="mermaid" id="mermaid-ewp5ipn">            sequenceDiagram
    前端-&gt;&gt;后端: POST /login (email, password)
    后端-&gt;&gt;前端: Set-Cookie: accessToken (15m), refreshToken (7d)
    前端-&gt;&gt;后端: GET /profile (自动带 Cookie)
    Note right of 后端: accessToken 过期？
    后端-&gt;&gt;前端: 401 + { message: &#39;Token expired&#39; }
    前端-&gt;&gt;后端: POST /refresh (自动带 refreshToken Cookie)
    后端-&gt;&gt;前端: 新 accessToken

          </pre></code><ul><li><p>刷新接口示例</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">app<span class="token punctuation">.</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string">&#39;/refresh&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span>req<span class="token punctuation">,</span> res<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> refreshToken <span class="token operator">=</span> req<span class="token punctuation">.</span>cookies<span class="token punctuation">.</span>refreshToken<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>refreshToken<span class="token punctuation">)</span> <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">sendStatus</span><span class="token punctuation">(</span><span class="token number">401</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  jwt<span class="token punctuation">.</span><span class="token function">verify</span><span class="token punctuation">(</span>refreshToken<span class="token punctuation">,</span> process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">REFRESH_TOKEN_SECRET</span><span class="token operator">!</span><span class="token punctuation">,</span> <span class="token punctuation">(</span>err<span class="token punctuation">,</span> user<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">sendStatus</span><span class="token punctuation">(</span><span class="token number">403</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 生成新 Access Token</span></span>
<span class="line">    <span class="token keyword">const</span> newAccessToken <span class="token operator">=</span> jwt<span class="token punctuation">.</span><span class="token function">sign</span><span class="token punctuation">(</span></span>
<span class="line">      <span class="token punctuation">{</span> userId<span class="token operator">:</span> user<span class="token punctuation">.</span>userId <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">JWT_SECRET</span><span class="token operator">!</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span> expiresIn<span class="token operator">:</span> <span class="token string">&#39;15m&#39;</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">{</span> accessToken<span class="token operator">:</span> newAccessToken <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><h3 id="_4-3-7-在-nestjs-中使用-官方推荐方式" tabindex="-1"><a class="header-anchor" href="#_4-3-7-在-nestjs-中使用-官方推荐方式"><span>4.3.7 在 NestJS 中使用（官方推荐方式）</span></a></h3><p>NestJS 官方提供 <code>@nestjs/jwt</code> 包，封装了 <code>jsonwebtoken</code>：</p><ol><li><p>安装</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> <span class="token function">install</span> @nestjs/jwt</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li><p>使用</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// auth.service.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> JwtService <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/jwt&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Injectable</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">AuthService</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">private</span> jwtService<span class="token operator">:</span> JwtService<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">async</span> <span class="token function">login</span><span class="token punctuation">(</span>user<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> payload <span class="token operator">=</span> <span class="token punctuation">{</span> email<span class="token operator">:</span> user<span class="token punctuation">.</span>email<span class="token punctuation">,</span> sub<span class="token operator">:</span> user<span class="token punctuation">.</span>userId <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">      access_token<span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>jwtService<span class="token punctuation">.</span><span class="token function">sign</span><span class="token punctuation">(</span>payload<span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">        expiresIn<span class="token operator">:</span> <span class="token string">&#39;1d&#39;</span><span class="token punctuation">,</span></span>
<span class="line">        secret<span class="token operator">:</span> process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">JWT_SECRET</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>自动处理类型、异常，与 NestJS 依赖注入无缝集成。</p></blockquote></li></ol><h3 id="_4-3-8-安全最佳实践" tabindex="-1"><a class="header-anchor" href="#_4-3-8-安全最佳实践"><span>4.3.8 安全最佳实践</span></a></h3><table><thead><tr><th>风险</th><th>解决方案</th></tr></thead><tbody><tr><td><strong>密钥泄露</strong></td><td>使用环境变量（<code>.env</code>），绝不提交到 Git</td></tr><tr><td><strong>Token 被盗</strong></td><td>设置短过期时间（如 15 分钟），配合 Refresh Token</td></tr><tr><td><strong>XSS 攻击</strong></td><td>Token 存在 <code>localStorage</code> 有风险 → 改用 <strong>HttpOnly Cookie</strong></td></tr><tr><td><strong>重放攻击</strong></td><td>记录已用 Token ID（<code>jti</code>）并加入黑名单</td></tr><tr><td><strong>算法混淆</strong></td><td>强制使用 <code>HS256</code>，避免 <code>none</code> 算法</td></tr></tbody></table><h3 id="_4-3-9-常见问题" tabindex="-1"><a class="header-anchor" href="#_4-3-9-常见问题"><span>4.3.9 常见问题</span></a></h3><ul><li><p>Q1: JWT 和 Session 有什么区别？</p><table><thead><tr><th>JWT</th><th>Session</th></tr></thead><tbody><tr><td>无状态（服务端不存）</td><td>有状态（服务端存 Session）</td></tr><tr><td>适合分布式系统</td><td>需要 Session 共享（如 Redis）</td></tr><tr><td>Payload 有大小限制</td><td>无限制</td></tr><tr><td>无法主动失效</td><td>可随时销毁 Session</td></tr></tbody></table></li><li><p>Q2: 该用 HS256 还是 RS256？</p><ul><li><strong>HS256</strong>：对称加密（同一密钥签发/验证），简单，适合单体应用</li><li><strong>RS256</strong>：非对称加密（私钥签发，公钥验证），适合微服务（各服务只需公钥）</li></ul></li><li><p>Q3: 如何注销 JWT？</p><ul><li><strong>短期有效</strong>：等待自然过期</li><li><strong>黑名单</strong>：将失效 Token 加入 Redis（需检查每次请求）</li><li><strong>修改密钥</strong>：强制所有 Token 失效（影响所有用户）</li></ul></li></ul>`,39)])])}const i=s(e,[["render",o]]),u=JSON.parse('{"path":"/backend/quote/backend/04.html","title":"四、前端解析","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1771996569000,"contributors":[{"name":"zhao-farmer","username":"zhao-farmer","email":"857899180@qq.com","commits":1,"url":"https://github.com/zhao-farmer"}],"changelog":[{"hash":"6456dcf1fd45f82d71ce5dfe3954468d5bf78145","time":1771996569000,"email":"857899180@qq.com","author":"zhao-farmer","message":"新提交"}]},"filePathRelative":"backend/quote/backend/04.md"}');export{i as comp,u as data};
